// Development-only oracle; no Rust implementation participates in expected output.
import {createRequire} from 'node:module';
import {execFileSync} from 'node:child_process';
import {readFileSync,writeFileSync} from 'node:fs';
import {dirname,join,resolve} from 'node:path';
import {fileURLToPath} from 'node:url';
const root=resolve(process.argv[2]);
const revision='6aa358ccbae30fbf27318f79ee183212f726f9ba';
if(execFileSync('git',['-C',root,'rev-parse','HEAD'],{encoding:'utf8'}).trim()!==revision)throw Error('Wrong reference revision');
const require=createRequire(join(root,'package.json'));
const {findFileCycles}=require('./dist/graph/file-cycles.js');
const cases=[];
function add(id,arcs){const pairs=arcs.map(([source,target])=>({source,target}));cases.push({id,pairs,expected:findFileCycles(pairs)});}
add('empty',[]);
add('self-edges',[['a','a']]);
add('chain',[['a','b'],['b','c']]);
add('two-groups',[['a','b'],['b','a'],['c','d'],['d','e'],['e','c'],['b','c']]);
add('duplicates',[['a','b'],['a','b'],['b','a'],['b','b']]);
let state=7717;
const random=()=>{state=(Math.imul(state,1664525)+1013904223)>>>0;return state;};
for(let c=0;c<100;c++){const arcs=[],size=3+random()%30;for(let n=0;n<size*2;n++)arcs.push([`file${random()%size}.ts`,`file${random()%size}.ts`]);add(`graph-${c}`,arcs);}
const destination=dirname(fileURLToPath(import.meta.url));
writeFileSync(join(destination,'cycles.json'),JSON.stringify({revision,cases},null,2)+'\n');
writeFileSync(join(destination,'LICENSE'),readFileSync(join(root,'LICENSE')));
const ts=require('typescript');
const {isTestPath,isTestFile}=require('./dist/search/query-utils.js');
const {isGeneratedFile,hasGeneratedHeader,detectGeneratedFile}=require('./dist/extraction/generated-detection.js');
const paths=new Set(['src/example/Worker.ts','examples/src/main/Worker.ts','src/main/java/samples/Worker.java','src/androidTest/Worker.kt','testdata/data.go','latest.kt','test/helper.rs','fixtures/data.ts']);
const sources=new Set(['\ufeff// Code generated by tool. DO NOT EDIT.', '\u0085// Code generated by tool. DO NOT EDIT.', '', '// Code generated by tool. DO NOT EDIT.\nfunction work() {}', 'const banner = "Code generated by tool. DO NOT EDIT.";', '/*\nCode generated by tool. DO NOT EDIT.\n*/', '// @generated\n', '// @@generated\n', '// foo@generated\n', '// example \n'.repeat(60)+'// @generated\n', '// example \n'.repeat(59)+'// @generated\n', '// '+ '😀'.repeat(4100)+'\n// @generated\n', 'function x(){a();}'.repeat(300), 'const data = "'+'x'.repeat(5000)+'";']);
for(const name of ['generated-detection.test.ts','dead-code.test.ts']){
 const source=readFileSync(join(root,'__tests__',name),'utf8'),tree=ts.createSourceFile(name,source,ts.ScriptTarget.Latest,true);
 function visit(node){if(ts.isStringLiteral(node)||ts.isNoSubstitutionTemplateLiteral(node)){const value=node.text;if(value.length<200&&!value.includes('\n')&&/[/.]/.test(value))paths.add(value);if(value.includes('\n')||/generat/i.test(value))sources.add(value);}ts.forEachChild(node,visit);}
 visit(tree);
}
writeFileSync(join(destination,'classification.json'),JSON.stringify({revision,paths:[...paths].map(path=>({path,testPath:isTestPath(path),testFile:isTestFile(path),generatedPath:isGeneratedFile(path)})),sources:[...sources].map(source=>({source,header:hasGeneratedHeader(source),generated:detectGeneratedFile('bundle.js',source)}))},null,2)+'\n');
